import{d as e,i as t}from"./index-BVdLvPw-.js";import{t as n}from"./BlogPost-BCN0DswP.js";var r=t();function i(){return(0,r.jsxs)(n,{path:`/blog-microsoft-365-plans-compared`,geoNote:!0,children:[(0,r.jsx)(`p`,{children:`Microsoft 365 is the backbone of most modern offices: email, files, meetings and the Office apps. But with several business plans to choose from, many businesses pay for more than they need, or miss security features they should have.`}),(0,r.jsx)(`p`,{children:`This guide compares the three main business plans in plain English, explains where Copilot fits, and shows how to choose the right plan for each person rather than for the whole business.`}),(0,r.jsx)(`h2`,{children:`The three main business plans`}),(0,r.jsx)(`p`,{children:`The Business plans are designed for organisations with up to 300 users. If you need more than 300 seats on a plan, you will usually look at Enterprise plans such as Microsoft 365 E3 instead.`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Business Basic:`}),` web and mobile Office apps, business email, Teams and 1 TB of OneDrive. Ideal for staff who mostly work in a browser or on a phone.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Business Standard:`}),` everything in Basic plus the desktop Office apps, such as Word, Excel, PowerPoint and Outlook, installed on computers. The usual choice for office staff. It is also sold as Business Standard with Copilot.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Business Premium:`}),` everything in Standard plus Defender for Business, Intune device management and Entra ID identity protection. Our recommendation for any business that handles sensitive data. It is also sold as Business Premium with Copilot.`]})]}),(0,r.jsx)(`p`,{children:`Each plan is billed per user, so the right mix depends on how your people work. We quote licences clearly in writing.`}),(0,r.jsx)(`h2`,{children:`What the security features in Premium actually do`}),(0,r.jsx)(`p`,{children:`Premium is the plan people most often struggle to justify, because its extra value is in security rather than in apps people see every day. Here is what the main parts do:`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Microsoft Entra ID P1:`}),` adds Conditional Access, which lets you set rules such as requiring multi-factor authentication, blocking sign-ins from overseas, or only allowing access from company-managed devices.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Microsoft Intune:`}),` manages laptops and phones from one place. You can push security settings and updates, require encryption, and wipe company data from a lost or stolen device.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Defender for Business:`}),` endpoint protection that detects and responds to threats on computers, going further than basic antivirus.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Email and data protection:`}),` stronger protection against phishing links and malicious attachments, plus tools to label and protect sensitive information.`]})]}),(0,r.jsx)(`p`,{children:`Microsoft has also added extra mailbox storage and email security features to Standard and Premium during 2026. Features change from time to time, so check Microsoft’s current plan comparison before you decide.`}),(0,r.jsx)(`h2`,{children:`Where Copilot fits`}),(0,r.jsx)(`p`,{children:`Microsoft 365 users can use Copilot Chat, which answers questions using the web, as part of their plan. The full Microsoft 365 Copilot, which works with your emails, files, chats and meetings inside Word, Excel, Outlook and Teams, needs a Copilot licence.`}),(0,r.jsxs)(`p`,{children:[`You can get that licence in two ways: buy a Business Standard or Business Premium plan with Copilot included, or add a Copilot licence to an existing plan for the people who need it. Before you roll it out, read our guide on `,(0,r.jsx)(e,{to:`/blog-copilot-readiness`,children:`getting your business ready for Copilot`}),`, because Copilot can surface any file a user already has access to.`]}),(0,r.jsx)(`h2`,{children:`You don't have to give everyone the same plan`}),(0,r.jsx)(`p`,{children:`Microsoft lets you mix plans within one account. A warehouse worker who only needs email and Teams on a phone can be on Business Basic, while your finance team is on Business Premium. Mixing plans is often the fastest way to cut your monthly bill.`}),(0,r.jsx)(`h3`,{children:`A worked example`}),(0,r.jsx)(`p`,{children:`Picture a 20-person trades business in Melbourne. Eight field staff use email, Teams and a job app on their phones. Ten office staff write quotes in Word and build reports in Excel. Two managers handle payroll and client contracts.`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsx)(`li`,{children:`The eight field staff go on Business Basic.`}),(0,r.jsx)(`li`,{children:`The office staff would suit Business Standard, but because they work from home on some days, Business Premium is the safer choice.`}),(0,r.jsx)(`li`,{children:`The two managers go on Business Premium, and perhaps Copilot, to help with reports and summaries.`})]}),(0,r.jsx)(`p`,{children:`One catch: some Premium protections, such as Conditional Access rules, only protect the users who hold the licence. Leaving a few people on lower plans can leave gaps. Review this with whoever manages your security.`}),(0,r.jsx)(`h2`,{children:`When Business Premium is worth it`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsx)(`li`,{children:`You store client, health or financial information.`}),(0,r.jsx)(`li`,{children:`Staff work from home or on personal devices.`}),(0,r.jsxs)(`li`,{children:[`You want to align with the `,(0,r.jsx)(e,{to:`/blog-essential-eight-guide`,children:`ASD Essential Eight`}),`.`]}),(0,r.jsx)(`li`,{children:`You have had phishing or account takeover attempts.`})]}),(0,r.jsx)(`h2`,{children:`Common mistakes`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsx)(`li`,{children:`Buying Premium for everyone but never switching on its security features.`}),(0,r.jsx)(`li`,{children:`Paying for licences for staff who have left the business.`}),(0,r.jsx)(`li`,{children:`Giving desktop apps to staff who only ever use a browser or phone.`}),(0,r.jsx)(`li`,{children:`Choosing annual or monthly terms without understanding the cancellation rules.`}),(0,r.jsx)(`li`,{children:`Assuming Microsoft backs up everything for you. Retention is not the same as a tested backup.`})]}),(0,r.jsx)(`h3`,{children:`A quick checklist before you choose`}),(0,r.jsxs)(`ol`,{children:[(0,r.jsx)(`li`,{children:`List every user and the devices they use.`}),(0,r.jsx)(`li`,{children:`Note who needs desktop apps and who works only in a browser.`}),(0,r.jsx)(`li`,{children:`Mark anyone who handles sensitive client, health or financial data.`}),(0,r.jsx)(`li`,{children:`Decide who would genuinely benefit from Copilot.`}),(0,r.jsx)(`li`,{children:`Remove licences for inactive or shared accounts.`})]}),(0,r.jsx)(`h2`,{children:`Frequently asked questions`}),(0,r.jsx)(`h3`,{children:`Can we change plans later?`}),(0,r.jsx)(`p`,{children:`Yes. You can usually move users up to a higher plan at any time. Moving down or reducing seats may be limited until your subscription term ends, so check the terms before you commit.`}),(0,r.jsx)(`h3`,{children:`Is Business Basic enough for a small office?`}),(0,r.jsx)(`p`,{children:`It can be if everyone is happy working in the web versions of Word and Excel. If people regularly use advanced Excel features or Outlook on a desktop, Standard is the better fit.`}),(0,r.jsx)(`h3`,{children:`Do we need Premium if we already have antivirus?`}),(0,r.jsxs)(`p`,{children:[`Antivirus is only one layer. Premium adds device management, sign-in rules and identity protection, which help stop the account takeovers that antivirus does not cover. Our `,(0,r.jsx)(e,{to:`/cybersecurity`,children:`cybersecurity team`}),` can explain what you would gain.`]}),(0,r.jsx)(`h3`,{children:`Can you move our existing licences?`}),(0,r.jsx)(`p`,{children:`In most cases, yes. We plan the move with you so email and files keep working during the change.`}),(0,r.jsx)(`h2`,{children:`How we help`}),(0,r.jsxs)(`p`,{children:[`We review every user, recommend the right plan for each, move your licences across with no downtime and configure security properly. `,(0,r.jsx)(e,{to:`/microsoft-licensing`,children:`See Microsoft Licensing`}),` or `,(0,r.jsx)(e,{to:`/contact?service=Microsoft+Licensing`,children:`get a quote`}),`.`]})]})}export{i as default};